-- seed_tables.sql — the 12 dining tables of "Napoli Pizza & Grill".
-- Safe to re-run: removes this restaurant's bookings and tables, then re-inserts.
-- Paste into the Supabase SQL Editor and run. Requires 0006_bookings.sql and seed.sql.
--
-- Fixed ids (same scheme as seed.sql): 66666666-0000-0000-0000-0000000000NN
-- Layout: T1-T4 two-seaters, T5-T9 four-seaters, T10-T11 six-seaters, T12 eight-seater.

begin;

-- NOTE: this also removes the demo restaurant's bookings.
delete from public.bookings          where restaurant_id = '11111111-1111-1111-1111-111111111111';
delete from public.restaurant_tables where restaurant_id = '11111111-1111-1111-1111-111111111111';


commit;
